1: const { sql, getPool, executeTransaction } = require('../config/db');
2: 
3: class MovementsService {
4:   async getAllMovements() {
5:     const pool = await getPool();
6:     const result = await pool.request().query(`
7:       SELECT m.*, i.nombre as item_nombre, i.codigo as item_codigo
8:       FROM movimientos_inventario m
9:       INNER JOIN items_inventario i ON m.item_id = i.id
10:       ORDER BY m.fecha_movimiento DESC
11:     `);
12:     return result.recordset;
13:   }
14: 
15:   async createMovement(data, userId) {
16:     const { item_id, tipo_movimiento, cantidad, motivo, referencia } = data;
17: 
18:     return await executeTransaction(async (transaction) => {
19:       // 1. Obtener stock actual
20:       const itemResult = await transaction.request()
21:         .input('item_id', sql.Int, item_id)
22:         .query('SELECT stock_actual FROM items_inventario WHERE id = @item_id');
23: 
24:       if (itemResult.recordset.length === 0) {
25:         throw new Error('Item no encontrado');
26:       }
27: 
28:       const stock_anterior = itemResult.recordset[0].stock_actual;
29:       const stock_nuevo = tipo_movimiento === 'ENTRADA' 
30:         ? stock_anterior + parseInt(cantidad)
31:         : stock_anterior - parseInt(cantidad);
32: 
33:       // 2. Crear movimiento
34:       await transaction.request()
35:         .input('item_id', sql.Int, item_id)
36:         .input('tipo_movimiento', sql.VarChar, tipo_movimiento)
37:         .input('cantidad', sql.Int, parseInt(cantidad))
38:         .input('stock_anterior', sql.Int, stock_anterior)
39:         .input('stock_nuevo', sql.Int, stock_nuevo)
40:         .input('motivo', sql.VarChar, motivo)
41:         .input('referencia', sql.VarChar, referencia)
42:         .input('creado_por', sql.Int, userId)
43:         .query(`
44:           INSERT INTO movimientos_inventario (
45:             item_id, tipo_movimiento, cantidad, stock_anterior, stock_nuevo,
46:             motivo, referencia, fecha_movimiento, creado_por
47:           ) VALUES (
48:             @item_id, @tipo_movimiento, @cantidad, @stock_anterior, @stock_nuevo,
49:             @motivo, @referencia, GETDATE(), @creado_por
50:           )
51:         `);
52: 
53:       // 3. Actualizar stock del item
54:       await transaction.request()
55:         .input('stock_nuevo', sql.Int, stock_nuevo)
56:         .input('item_id', sql.Int, item_id)
57:         .query('UPDATE items_inventario SET stock_actual = @stock_nuevo WHERE id = @item_id');
58: 
59:       return { message: 'Movimiento registrado exitosamente' };
60:     });
61:   }
62: }
